// EXPORTS: ITdeeInput, ITdeeResult, calculateTdee
export interface ITdeeInput {
  gender: 'male' | 'female'
  age: number
  height: number // cm
  weight: number // kg
  activityLevel: 1 | 2 | 3 | 4 | 5
}

export interface ITdeeResult {
  bmr: number
  tdee: number
  fatLossMin: number
  fatLossMax: number
  deficitMin: number
  deficitMax: number
  weeklyLossMin: string
  weeklyLossMax: string
}

const ACTIVITY_COEFFICIENTS: Record<number, number> = {
  1: 1.2,   // 久坐
  2: 1.375, // 轻度活动
  3: 1.55,  // 中度活动
  4: 1.725, // 高强度活动
  5: 1.9,   // 极高强度活动
}

export const ACTIVITY_LABELS: Record<number, string> = {
  1: '久坐（几乎不运动）',
  2: '轻度（每周1-3次）',
  3: '中度（每周3-5次）',
  4: '高强度（每周6-7次）',
  5: '极高强度（体力劳动+运动）',
}

export function calculateTdee(input: ITdeeInput): ITdeeResult {
  // Mifflin-St Jeor 公式
  const bmrBase = 10 * input.weight + 6.25 * input.height - 5 * input.age
  const bmr = input.gender === 'male' ? bmrBase + 5 : bmrBase - 161

  const coefficient = ACTIVITY_COEFFICIENTS[input.activityLevel]
  const tdee = Math.round(bmr * coefficient)

  // 减脂期建议摄入：TDEE 的 80% - 90%
  const fatLossMin = Math.round(tdee * 0.8)
  const fatLossMax = Math.round(tdee * 0.9)

  const deficitMin = tdee - fatLossMax
  const deficitMax = tdee - fatLossMin

  // 每斤脂肪约 3850 大卡，按每周 7 天估算
  const weeklyLossMin = (deficitMin * 7 / 3850).toFixed(1)
  const weeklyLossMax = (deficitMax * 7 / 3850).toFixed(1)

  return {
    bmr: Math.round(bmr),
    tdee,
    fatLossMin,
    fatLossMax,
    deficitMin,
    deficitMax,
    weeklyLossMin,
    weeklyLossMax,
  }
}