import { useState, useEffect } from 'react';
import { NavLink } from '@lark-apaas/client-toolkit-lite';
import { Menu, X, Scale } from 'lucide-react';
import { useIsMobile } from '@/hooks/use-mobile';

const NAV_ITEMS = [
  { label: 'BMI 计算', href: '#bmi' },
  { label: '热量计算', href: '#tdee' },
  { label: '体重记录', href: '#weight' },
  { label: '食物热量', href: '#foods' },
  { label: '运动推荐', href: '#exercise' },
];

export default function Header() {
  const isMobile = useIsMobile();
  const [open, setOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 20);
    onScroll();
    window.addEventListener('scroll', onScroll);
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header
      className={`sticky top-0 z-50 w-full transition-all duration-300 ${
        scrolled
          ? 'bg-background/80 backdrop-blur-md border-b border-border/40 shadow-xs'
          : 'bg-transparent backdrop-blur-sm'
      }`}
    >
      <div className="max-w-7xl mx-auto px-4 md:px-6 flex h-16 items-center justify-between">
        <NavLink
          to="#hero"
          className="flex items-center gap-2 font-bold text-foreground"
        >
          <div className="size-8 rounded-lg bg-primary text-primary-foreground flex items-center justify-center">
            <Scale className="size-5" />
          </div>
          <span className="text-lg tracking-tight">减肥工具箱</span>
        </NavLink>

        {!isMobile && (
          <nav className="flex items-center gap-1">
            {NAV_ITEMS.map((item) => (
              <NavLink
                key={item.href}
                to={item.href}
                className={({ isActive }) =>
                  `px-3 py-2 text-sm rounded-md transition-colors ${
                    isActive
                      ? 'text-primary font-medium bg-primary/10'
                      : 'text-muted-foreground hover:text-foreground hover:bg-accent/50'
                  }`
                }
              >
                {item.label}
              </NavLink>
            ))}
          </nav>
        )}

        {isMobile && (
          <button
            type="button"
            onClick={() => setOpen((v) => !v)}
            className="p-2 rounded-md text-foreground hover:bg-accent/50 transition-colors"
            aria-label="菜单"
          >
            {open ? <X className="size-5" /> : <Menu className="size-5" />}
          </button>
        )}
      </div>

      {isMobile && open && (
        <div className="border-t border-border/40 bg-background/95 backdrop-blur-md">
          <nav className="max-w-7xl mx-auto px-4 py-3 flex flex-col gap-1">
            {NAV_ITEMS.map((item) => (
              <NavLink
                key={item.href}
                to={item.href}
                onClick={() => setOpen(false)}
                className={({ isActive }) =>
                  `px-3 py-2.5 text-sm rounded-md transition-colors ${
                    isActive
                      ? 'text-primary font-medium bg-primary/10'
                      : 'text-muted-foreground hover:text-foreground hover:bg-accent/50'
                  }`
                }
              >
                {item.label}
              </NavLink>
            ))}
          </nav>
        </div>
      )}
    </header>
  );
}
