import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Dumbbell,
  Flame,
  Clock as ClockIcon,
  ChevronDown,
  Activity,
} from 'lucide-react';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { MOCK_EXERCISES } from '@/data/exercises';
import type { IExercise } from '@/data/exercises';

const INTENSITY_TABS = [
  { key: 'all', label: '全部' },
  { key: 'low', label: '低强度' },
  { key: 'medium', label: '中强度' },
  { key: 'high', label: '高强度' },
] as const;

const INTENSITY_META: Record<string, { label: string; color: string; bg: string }> = {
  low: {
    label: '低强度',
    color: 'text-emerald-700 dark:text-emerald-400',
    bg: 'bg-emerald-500/15',
  },
  medium: {
    label: '中强度',
    color: 'text-amber-700 dark:text-amber-400',
    bg: 'bg-amber-500/15',
  },
  high: {
    label: '高强度',
    color: 'text-rose-700 dark:text-rose-400',
    bg: 'bg-rose-500/15',
  },
};

export default function ExerciseSection() {
  const [intensity, setIntensity] = useState<string>('all');
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const filtered =
    intensity === 'all'
      ? MOCK_EXERCISES
      : MOCK_EXERCISES.filter((e) => e.intensity === intensity);

  return (
    <section id="exercise" className="w-full py-12 md:py-16 scroll-mt-20">
      <div className="max-w-7xl mx-auto px-4 md:px-6">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-80px' }}
          transition={{ duration: 0.6 }}
          className="text-center mb-8 md:mb-10"
        >
          <Badge variant="outline" className="mb-3">
            <Dumbbell className="size-3.5 mr-1" />
            工具 05
          </Badge>
          <h2 className="text-2xl md:text-3xl font-bold text-foreground">
            居家运动推荐
          </h2>
          <p className="text-muted-foreground mt-2 text-sm md:text-base">
            按强度分级选择，随时随地动起来
          </p>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-80px' }}
          transition={{ duration: 0.6, delay: 0.1 }}
        >
          <Card className="border-border/60 shadow-sm">
            <CardHeader className="pb-4">
              <div className="flex flex-wrap gap-2">
                {INTENSITY_TABS.map((t) => {
                  const active = intensity === t.key;
                  return (
                    <button
                      key={t.key}
                      type="button"
                      onClick={() => setIntensity(t.key)}
                      className={`px-4 py-2 rounded-full text-sm font-medium transition-all ${
                        active
                          ? 'bg-primary text-primary-foreground shadow-sm'
                          : 'bg-card text-muted-foreground hover:bg-accent border border-border/60'
                      }`}
                    >
                      {t.label}
                    </button>
                  );
                })}
              </div>
            </CardHeader>
            <CardContent>
              <AnimatePresence mode="wait">
                <motion.div
                  key={intensity}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -10 }}
                  transition={{ duration: 0.3 }}
                  className="grid md:grid-cols-2 lg:grid-cols-3 gap-4"
                >
                  {filtered.map((ex, i) => (
                    <ExerciseCard
                      key={ex.id}
                      exercise={ex}
                      index={i}
                      expanded={expandedId === ex.id}
                      onToggle={() =>
                        setExpandedId((prev) =>
                          prev === ex.id ? null : ex.id
                        )
                      }
                    />
                  ))}
                </motion.div>
              </AnimatePresence>
            </CardContent>
          </Card>
        </motion.div>
      </div>
    </section>
  );
}

function ExerciseCard({
  exercise,
  index,
  expanded,
  onToggle,
}: {
  exercise: IExercise;
  index: number;
  expanded: boolean;
  onToggle: () => void;
}) {
  const meta = INTENSITY_META[exercise.intensity];
  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.3, delay: index * 0.05 }}
    >
      <div className="h-full rounded-xl bg-card border border-border/60 hover:border-primary/30 hover:shadow-sm transition-all overflow-hidden">
        <button
          type="button"
          onClick={onToggle}
          className="w-full p-5 text-left"
        >
          <div className="flex items-start justify-between gap-3 mb-3">
            <div className="flex items-center gap-2.5">
              <div className="size-10 rounded-lg bg-primary/10 text-primary flex items-center justify-center shrink-0">
                <Dumbbell className="size-5" />
              </div>
              <h3 className="font-semibold text-foreground">{exercise.name}</h3>
            </div>
            <ChevronDown
              className={`size-5 text-muted-foreground shrink-0 transition-transform duration-300 ${
                expanded ? 'rotate-180' : ''
              }`}
            />
          </div>

          <div className="flex items-center gap-4 text-sm">
            <Badge variant="secondary" className={`${meta.bg} ${meta.color} border-0`}>
              {meta.label}
            </Badge>
            <span className="flex items-center gap-1 text-muted-foreground">
              <ClockIcon className="size-3.5" />
              {exercise.duration} 分钟
            </span>
            <span className="flex items-center gap-1 text-rose-500 font-medium">
              <Flame className="size-3.5" />
              {exercise.calories} 大卡
            </span>
          </div>
        </button>

        <AnimatePresence initial={false}>
          {expanded && (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              transition={{ duration: 0.3, ease: 'easeOut' }}
              className="overflow-hidden"
            >
              <div className="px-5 pb-5 pt-0 border-t border-border/40">
                <div className="pt-3">
                  <div className="text-xs text-muted-foreground mb-1.5 flex items-center gap-1">
                    <Activity className="size-3.5" />
                    动作说明
                  </div>
                  <p className="text-sm text-foreground/80 leading-relaxed">
                    {exercise.description}
                  </p>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </motion.div>
  );
}
