import { useState, useEffect, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useAutoAnimate } from '@formkit/auto-animate/react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import {
  TrendingDown,
  Plus,
  Trash2,
  CalendarDays,
  Scale as ScaleIcon,
  Clock,
  Target,
} from 'lucide-react';
import { scopedStorage } from '@lark-apaas/client-toolkit-lite';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';

interface IWeightRecord {
  id: string;
  date: string;
  weight: number;
}

const STORAGE_KEY = 'fit_track_weight_records';

const STATS = [
  { key: 'totalLoss', label: '累计减重', icon: TrendingDown, suffix: '斤' },
  { key: 'avgWeekly', label: '平均速度', icon: Target, suffix: '斤/周' },
  { key: 'days', label: '记录天数', icon: CalendarDays, suffix: '天' },
];

export default function WeightSection() {
  const [records, setRecords] = useState<IWeightRecord[]>([]);
  const [date, setDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [weight, setWeight] = useState<number | ''>('');
  const [loaded, setLoaded] = useState(false);
  const [listRef] = useAutoAnimate({ duration: 250 });

  // 初始加载
  useEffect(() => {
    try {
      const raw = scopedStorage.getItem(STORAGE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw) as IWeightRecord[];
        setRecords(parsed);
      }
    } catch {
      /* ignore */
    }
    setLoaded(true);
  }, []);

  // 持久化
  useEffect(() => {
    if (!loaded) return;
    try {
      scopedStorage.setItem(STORAGE_KEY, JSON.stringify(records));
    } catch {
      /* ignore */
    }
  }, [records, loaded]);

  const sortedRecords = useMemo(
    () => [...records].sort((a, b) => a.date.localeCompare(b.date)),
    [records]
  );

  const stats = useMemo(() => {
    if (sortedRecords.length < 2) {
      return { totalLoss: 0, avgWeekly: 0, days: sortedRecords.length };
    }
    const first = sortedRecords[0];
    const last = sortedRecords[sortedRecords.length - 1];
    const totalLossKg = first.weight - last.weight;
    const totalLossJin = +(totalLossKg * 2).toFixed(1);
    const days =
      Math.ceil(
        (new Date(last.date).getTime() - new Date(first.date).getTime()) /
          (1000 * 60 * 60 * 24)
      ) || 1;
    const avgWeekly = +((totalLossJin / days) * 7).toFixed(2);
    return {
      totalLoss: totalLossJin,
      avgWeekly,
      days: sortedRecords.length,
    };
  }, [sortedRecords]);

  const chartData = useMemo(
    () =>
      sortedRecords.map((r) => ({
        date: r.date.slice(5),
        weight: r.weight,
      })),
    [sortedRecords]
  );

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!weight || weight < 20 || weight > 300) {
      toast.error('请输入有效的体重（20-300 kg）');
      return;
    }
    if (!date) {
      toast.error('请选择日期');
      return;
    }
    // 同一天覆盖
    const existingIdx = records.findIndex((r) => r.date === date);
    if (existingIdx >= 0) {
      setRecords((prev) =>
        prev.map((r, i) => (i === existingIdx ? { ...r, weight: +weight } : r))
      );
      toast.success('已更新当日体重');
    } else {
      const newRecord: IWeightRecord = {
        id: Date.now().toString(),
        date,
        weight: +weight,
      };
      setRecords((prev) => [...prev, newRecord]);
      toast.success('已添加体重记录');
    }
    setWeight('');
  };

  const handleDelete = (id: string) => {
    setRecords((prev) => prev.filter((r) => r.id !== id));
    toast.success('已删除记录');
  };

  const reversed = useMemo(
    () => [...sortedRecords].reverse(),
    [sortedRecords]
  );

  return (
    <section id="weight" className="w-full py-12 md:py-16 scroll-mt-20">
      <div className="max-w-7xl mx-auto px-4 md:px-6">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-80px' }}
          transition={{ duration: 0.6 }}
          className="text-center mb-8 md:mb-10"
        >
          <Badge variant="outline" className="mb-3">
            <ScaleIcon className="size-3.5 mr-1" />
            工具 03
          </Badge>
          <h2 className="text-2xl md:text-3xl font-bold text-foreground">
            体重记录与趋势
          </h2>
          <p className="text-muted-foreground mt-2 text-sm md:text-base">
            记录每日体重，追踪变化趋势，数据保存在本地
          </p>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-80px' }}
          transition={{ duration: 0.6, delay: 0.1 }}
          className="grid lg:grid-cols-3 gap-6"
        >
          {/* 左侧：添加表单 + 统计 */}
          <div className="lg:col-span-1 space-y-6">
            <Card className="border-border/60 shadow-sm">
              <CardHeader className="pb-3">
                <CardTitle className="text-lg">添加记录</CardTitle>
                <CardDescription>记录今天的体重</CardDescription>
              </CardHeader>
              <CardContent>
                <form onSubmit={handleAdd} className="space-y-4">
                  <div className="space-y-2">
                    <Label htmlFor="weight-date">日期</Label>
                    <Input
                      id="weight-date"
                      type="date"
                      value={date}
                      onChange={(e) => setDate(e.target.value)}
                      className="h-11"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="weight-input">体重 (kg)</Label>
                    <Input
                      id="weight-input"
                      type="number"
                      step="0.1"
                      placeholder="例如 65.5"
                      value={weight}
                      onChange={(e) => {
                        const v = e.target.value;
                        setWeight(v === '' ? '' : parseFloat(v));
                      }}
                      className="h-11"
                    />
                  </div>
                  <Button type="submit" className="w-full h-11">
                    <Plus className="size-4 mr-1.5" />
                    添加记录
                  </Button>
                </form>
              </CardContent>
            </Card>

            <Card className="border-border/60 shadow-sm">
              <CardHeader className="pb-3">
                <CardTitle className="text-lg">数据统计</CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                {STATS.map((s) => {
                  const Icon = s.icon;
                  const val = stats[s.key as keyof typeof stats];
                  return (
                    <div
                      key={s.key}
                      className="flex items-center justify-between p-3 rounded-lg bg-muted/40"
                    >
                      <div className="flex items-center gap-2">
                        <Icon className="size-4 text-primary" />
                        <span className="text-sm text-muted-foreground">
                          {s.label}
                        </span>
                      </div>
                      <span className="text-lg font-bold tabular-nums text-foreground">
                        {val}
                        <span className="text-xs font-normal text-muted-foreground ml-0.5">
                          {s.suffix}
                        </span>
                      </span>
                    </div>
                  );
                })}
              </CardContent>
            </Card>
          </div>

          {/* 右侧：趋势图 + 记录列表 */}
          <div className="lg:col-span-2 space-y-6">
            <Card className="border-border/60 shadow-sm">
              <CardHeader className="pb-2">
                <CardTitle className="text-lg">体重趋势</CardTitle>
                <CardDescription>折线图展示体重变化</CardDescription>
              </CardHeader>
              <CardContent>
                {chartData.length >= 2 ? (
                  <div className="h-64 w-full">
                    <ResponsiveContainer width="100%" height="100%">
                      <LineChart data={chartData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                        <XAxis
                          dataKey="date"
                          tick={{ fontSize: 12, fill: 'hsl(var(--muted-foreground))' }}
                          stroke="hsl(var(--border))"
                        />
                        <YAxis
                          domain={['auto', 'auto']}
                          tick={{ fontSize: 12, fill: 'hsl(var(--muted-foreground))' }}
                          stroke="hsl(var(--border))"
                          width={40}
                        />
                        <Tooltip
                          contentStyle={{
                            background: 'hsl(var(--card))',
                            border: '1px solid hsl(var(--border))',
                            borderRadius: '8px',
                            fontSize: '13px',
                          }}
                          formatter={(value: number) => [`${value} kg`, '体重']}
                        />
                        <Line
                          type="monotone"
                          dataKey="weight"
                          stroke="hsl(var(--primary))"
                          strokeWidth={2.5}
                          dot={{ fill: 'hsl(var(--primary))', r: 4 }}
                          activeDot={{ r: 6 }}
                        />
                      </LineChart>
                    </ResponsiveContainer>
                  </div>
                ) : (
                  <div className="h-64 flex flex-col items-center justify-center text-center bg-muted/20 rounded-lg border border-dashed border-border/50">
                    <TrendingDown className="size-10 text-muted-foreground/40 mb-2" />
                    <p className="text-sm text-muted-foreground">
                      添加至少 2 条记录后显示趋势图
                    </p>
                  </div>
                )}
              </CardContent>
            </Card>

            <Card className="border-border/60 shadow-sm">
              <CardHeader className="pb-3">
                <CardTitle className="text-lg">历史记录</CardTitle>
                <CardDescription>
                  共 {records.length} 条记录
                </CardDescription>
              </CardHeader>
              <CardContent className="p-0">
                {reversed.length === 0 ? (
                  <div className="px-6 pb-6">
                    <div className="py-10 text-center bg-muted/20 rounded-lg border border-dashed border-border/50">
                      <ScaleIcon className="size-8 text-muted-foreground/40 mx-auto mb-2" />
                      <p className="text-sm text-muted-foreground">
                        还没有体重记录
                      </p>
                      <p className="text-xs text-muted-foreground/70 mt-1">
                        从今天开始记录吧
                      </p>
                    </div>
                  </div>
                ) : (
                  <ul ref={listRef} className="divide-y divide-border/50">
                    {reversed.map((r) => (
                      <li
                        key={r.id}
                        className="flex items-center justify-between px-6 py-3 hover:bg-muted/30 transition-colors"
                      >
                        <div className="flex items-center gap-3">
                          <div className="size-9 rounded-full bg-primary/10 text-primary flex items-center justify-center">
                            <ScaleIcon className="size-4" />
                          </div>
                          <div>
                            <div className="text-sm font-medium text-foreground">
                              {r.weight} kg
                            </div>
                            <div className="text-xs text-muted-foreground flex items-center gap-1">
                              <CalendarDays className="size-3" />
                              {r.date}
                            </div>
                          </div>
                        </div>
                        <Button
                          size="icon"
                          variant="ghost"
                          onClick={() => handleDelete(r.id)}
                          className="text-muted-foreground hover:text-destructive hover:bg-destructive/10"
                          aria-label="删除"
                        >
                          <Trash2 className="size-4" />
                        </Button>
                      </li>
                    ))}
                  </ul>
                )}
              </CardContent>
            </Card>
          </div>
        </motion.div>
      </div>
    </section>
  );
}
