import { useState, useMemo, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Scale, Info } from 'lucide-react';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';

interface BmiSectionProps {
  height: number | '';
  weight: number | '';
  onHeightChange: (v: number | '') => void;
  onWeightChange: (v: number | '') => void;
}

const BMI_RANGES = [
  { label: '偏瘦', min: 0, max: 18.5, color: 'bg-sky-500 text-white' },
  { label: '正常', min: 18.5, max: 24, color: 'bg-emerald-500 text-white' },
  { label: '超重', min: 24, max: 28, color: 'bg-amber-500 text-white' },
  { label: '肥胖', min: 28, max: 40, color: 'bg-rose-500 text-white' },
];

const SUGGESTIONS: Record<string, string> = {
  偏瘦: '体重偏轻，建议适量增加营养摄入，配合力量训练增肌。',
  正常: '体重在正常范围内，继续保持均衡饮食和规律运动。',
  超重: '体重略高，建议控制热量摄入，增加有氧运动，稳步减脂。',
  肥胖: '体重超标较多，建议制定科学减脂计划，必要时咨询专业人士。',
};

export default function BmiSection({
  height,
  weight,
  onHeightChange,
  onWeightChange,
}: BmiSectionProps) {
  const [mounted, setMounted] = useState(false);

  useEffect(() => setMounted(true), []);

  const result = useMemo(() => {
    if (!height || !weight || height < 50 || weight < 20) return null;
    const h = height / 100;
    const bmi = weight / (h * h);
    const level =
      bmi < 18.5 ? '偏瘦' : bmi < 24 ? '正常' : bmi < 28 ? '超重' : '肥胖';
    const range = BMI_RANGES.find((r) => r.label === level)!;
    return { bmi: bmi.toFixed(1), level, range };
  }, [height, weight]);

  // BMI 指针位置百分比（映射 14-35 到 0-100）
  const pointerPct = useMemo(() => {
    if (!result) return 0;
    const bmi = parseFloat(result.bmi);
    const clamped = Math.max(14, Math.min(35, bmi));
    return ((clamped - 14) / (35 - 14)) * 100;
  }, [result]);

  return (
    <section id="bmi" className="w-full py-12 md:py-16 scroll-mt-20">
      <div className="max-w-7xl mx-auto px-4 md:px-6">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-80px' }}
          transition={{ duration: 0.6 }}
          className="text-center mb-8 md:mb-10"
        >
          <Badge variant="outline" className="mb-3">
            <Scale className="size-3.5 mr-1" />
            工具 01
          </Badge>
          <h2 className="text-2xl md:text-3xl font-bold text-foreground">
            BMI 身体质量指数
          </h2>
          <p className="text-muted-foreground mt-2 text-sm md:text-base">
            输入身高体重，快速了解你的体重等级
          </p>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-80px' }}
          transition={{ duration: 0.6, delay: 0.1 }}
        >
          <Card className="border-border/60 shadow-sm">
            <CardContent className="p-6 md:p-8">
              <div className="grid md:grid-cols-2 gap-8 md:gap-10">
                {/* 输入区 */}
                <div className="space-y-5">
                  <div className="space-y-2">
                    <Label htmlFor="bmi-height">身高 (cm)</Label>
                    <Input
                      id="bmi-height"
                      type="number"
                      inputMode="decimal"
                      placeholder="例如 170"
                      value={height}
                      onChange={(e) => {
                        const v = e.target.value;
                        onHeightChange(v === '' ? '' : parseFloat(v));
                      }}
                      className="h-12 text-base"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="bmi-weight">体重 (kg)</Label>
                    <Input
                      id="bmi-weight"
                      type="number"
                      inputMode="decimal"
                      placeholder="例如 65"
                      value={weight}
                      onChange={(e) => {
                        const v = e.target.value;
                        onWeightChange(v === '' ? '' : parseFloat(v));
                      }}
                      className="h-12 text-base"
                    />
                  </div>
                  <div className="flex items-start gap-2 p-3 rounded-lg bg-muted/50 text-xs text-muted-foreground">
                    <Info className="size-4 shrink-0 mt-0.5" />
                    <span>
                      BMI = 体重(kg) ÷ 身高(m)²，
                      参考中国成人标准：18.5以下偏瘦 / 18.5-23.9正常 /
                      24-27.9超重 / 28以上肥胖
                    </span>
                  </div>
                </div>

                {/* 结果区 */}
                <div className="flex flex-col justify-center">
                  {result ? (
                    <motion.div
                      key="result"
                      initial={{ opacity: 0, scale: 0.95 }}
                      animate={{ opacity: 1, scale: 1 }}
                      transition={{ duration: 0.4 }}
                      className="space-y-5"
                    >
                      <div className="text-center">
                        <div className="text-sm text-muted-foreground mb-1">
                          你的 BMI 指数
                        </div>
                        <div className="flex items-baseline justify-center gap-1">
                          <span className="text-5xl md:text-6xl font-bold text-foreground tabular-nums">
                            {result.bmi}
                          </span>
                          <span className="text-muted-foreground">kg/m²</span>
                        </div>
                        <Badge
                          className={`mt-3 ${result.range.color}`}
                          variant="default"
                        >
                          {result.level}
                        </Badge>
                      </div>

                      {/* 进度条 */}
                      <div className="space-y-2">
                        <div className="relative h-3 rounded-full overflow-hidden flex">
                          {BMI_RANGES.map((r) => {
                            const width =
                              ((r.max - r.min) / (35 - 14)) * 100;
                            return (
                              <div
                                key={r.label}
                                className={`${r.color} opacity-80`}
                                style={{ width: `${width}%` }}
                                title={`${r.label}: ${r.min}-${r.max}`}
                              />
                            );
                          })}
                          {/* 指针 */}
                          <div
                            className="absolute top-0 bottom-0 w-0.5 bg-foreground shadow-[0_0_0_2px_rgba(255_255_255_0.8)]"
                            style={{
                              left: `${pointerPct}%`,
                              transform: 'translateX(-50%)',
                              transition: 'left 0.6s cubic-bezier(0.16,1,0.3,1)',
                            }}
                          />
                        </div>
                        <div className="flex justify-between text-[10px] md:text-xs text-muted-foreground">
                          <span>14</span>
                          <span>18.5</span>
                          <span>24</span>
                          <span>28</span>
                          <span>35</span>
                        </div>
                      </div>

                      <div className="p-4 rounded-lg bg-primary/5 border border-primary/20 text-sm text-foreground/90">
                        💡 {SUGGESTIONS[result.level]}
                      </div>
                    </motion.div>
                  ) : (
                    <motion.div
                      key="placeholder"
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      transition={{ duration: 0.4 }}
                      className="flex flex-col items-center justify-center h-full min-h-[200px] text-center space-y-3 bg-muted/30 rounded-xl border border-dashed border-border/60"
                    >
                      <Scale className="size-10 text-muted-foreground/50" />
                      <div>
                        <p className="text-sm font-medium text-muted-foreground">
                          输入身高和体重
                        </p>
                        <p className="text-xs text-muted-foreground/70 mt-1">
                          结果将自动计算显示
                        </p>
                      </div>
                    </motion.div>
                  )}
                </div>
              </div>
            </CardContent>
          </Card>
        </motion.div>
      </div>
    </section>
  );
}
