import { useMemo } from 'react';
import { motion } from 'framer-motion';
import { Flame, Zap, Target, TrendingDown } from 'lucide-react';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { calculateTdee, ACTIVITY_LABELS } from '@/data/tdee';
import type { ITdeeInput } from '@/data/tdee';

interface TdeeSectionProps {
  gender: 'male' | 'female';
  age: number | '';
  height: number | '';
  weight: number | '';
  activityLevel: number;
  onGenderChange: (v: 'male' | 'female') => void;
  onAgeChange: (v: number | '') => void;
  onHeightChange: (v: number | '') => void;
  onWeightChange: (v: number | '') => void;
  onActivityLevelChange: (v: number) => void;
}

const STATS = [
  { key: 'bmr', label: '基础代谢 BMR', icon: Zap, suffix: '大卡/天' },
  { key: 'tdee', label: '每日总消耗 TDEE', icon: Flame, suffix: '大卡/天' },
];

export default function TdeeSection({
  gender,
  age,
  height,
  weight,
  activityLevel,
  onGenderChange,
  onAgeChange,
  onHeightChange,
  onWeightChange,
  onActivityLevelChange,
}: TdeeSectionProps) {
  const result = useMemo(() => {
    if (!age || !height || !weight || age < 10 || height < 50 || weight < 20)
      return null;
    const input: ITdeeInput = {
      gender,
      age: age as number,
      height: height as number,
      weight: weight as number,
      activityLevel: activityLevel as ITdeeInput['activityLevel'],
    };
    return calculateTdee(input);
  }, [gender, age, height, weight, activityLevel]);

  return (
    <section id="tdee" className="w-full py-12 md:py-16 bg-muted/30 scroll-mt-20">
      <div className="max-w-7xl mx-auto px-4 md:px-6">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-80px' }}
          transition={{ duration: 0.6 }}
          className="text-center mb-8 md:mb-10"
        >
          <Badge variant="outline" className="mb-3">
            <Flame className="size-3.5 mr-1" />
            工具 02
          </Badge>
          <h2 className="text-2xl md:text-3xl font-bold text-foreground">
            每日热量需求 TDEE
          </h2>
          <p className="text-muted-foreground mt-2 text-sm md:text-base">
            计算每日总消耗热量，给出减脂期建议摄入范围
          </p>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-80px' }}
          transition={{ duration: 0.6, delay: 0.1 }}
        >
          <Card className="border-border/60 shadow-sm">
            <CardContent className="p-6 md:p-8">
              <div className="grid md:grid-cols-2 gap-8 md:gap-10">
                {/* 输入区 */}
                <div className="space-y-4">
                  <div className="space-y-2">
                    <Label>性别</Label>
                    <div className="grid grid-cols-2 gap-2">
                      <button
                        type="button"
                        onClick={() => onGenderChange('male')}
                        className={`h-11 rounded-md text-sm font-medium transition-all ${
                          gender === 'male'
                            ? 'bg-primary text-primary-foreground shadow-sm'
                            : 'bg-muted text-muted-foreground hover:bg-accent'
                        }`}
                      >
                        男性
                      </button>
                      <button
                        type="button"
                        onClick={() => onGenderChange('female')}
                        className={`h-11 rounded-md text-sm font-medium transition-all ${
                          gender === 'female'
                            ? 'bg-primary text-primary-foreground shadow-sm'
                            : 'bg-muted text-muted-foreground hover:bg-accent'
                        }`}
                      >
                        女性
                      </button>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    <div className="space-y-2">
                      <Label htmlFor="tdee-age">年龄 (岁)</Label>
                      <Input
                        id="tdee-age"
                        type="number"
                        placeholder="25"
                        value={age}
                        onChange={(e) => {
                          const v = e.target.value;
                          onAgeChange(v === '' ? '' : parseInt(v, 10));
                        }}
                        className="h-11"
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="tdee-height">身高 (cm)</Label>
                      <Input
                        id="tdee-height"
                        type="number"
                        placeholder="170"
                        value={height}
                        onChange={(e) => {
                          const v = e.target.value;
                          onHeightChange(v === '' ? '' : parseFloat(v));
                        }}
                        className="h-11"
                      />
                    </div>
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="tdee-weight">体重 (kg)</Label>
                    <Input
                      id="tdee-weight"
                      type="number"
                      placeholder="65"
                      value={weight}
                      onChange={(e) => {
                        const v = e.target.value;
                        onWeightChange(v === '' ? '' : parseFloat(v));
                      }}
                      className="h-11"
                    />
                  </div>

                  <div className="space-y-2">
                    <Label>活动量</Label>
                    <Select
                      value={String(activityLevel)}
                      onValueChange={(v) => onActivityLevelChange(parseInt(v, 10))}
                    >
                      <SelectTrigger className="h-11">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {Object.entries(ACTIVITY_LABELS).map(([k, v]) => (
                          <SelectItem key={k} value={k}>
                            {v}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                </div>

                {/* 结果区 */}
                <div className="flex flex-col justify-center">
                  {result ? (
                    <motion.div
                      key="result"
                      initial={{ opacity: 0, scale: 0.95 }}
                      animate={{ opacity: 1, scale: 1 }}
                      transition={{ duration: 0.4 }}
                      className="space-y-5"
                    >
                      <div className="grid grid-cols-2 gap-3">
                        {STATS.map((s) => {
                          const Icon = s.icon;
                          const val = result[s.key as 'bmr' | 'tdee'];
                          return (
                            <div
                              key={s.key}
                              className="p-4 rounded-xl bg-card border border-border/60"
                            >
                              <div className="flex items-center gap-1.5 text-xs text-muted-foreground mb-1">
                                <Icon className="size-3.5 text-primary" />
                                {s.label}
                              </div>
                              <div className="text-2xl font-bold text-foreground tabular-nums">
                                {val}
                              </div>
                              <div className="text-xs text-muted-foreground">
                                {s.suffix}
                              </div>
                            </div>
                          );
                        })}
                      </div>

                      <div className="p-5 rounded-xl bg-gradient-to-br from-primary/10 to-secondary/30 border border-primary/20">
                        <div className="flex items-center gap-2 text-sm font-medium text-foreground mb-2">
                          <Target className="size-4 text-primary" />
                          减脂期建议摄入
                        </div>
                        <div className="flex items-baseline gap-1">
                          <span className="text-3xl font-bold text-foreground tabular-nums">
                            {result.fatLossMin}
                          </span>
                          <span className="text-muted-foreground">~</span>
                          <span className="text-3xl font-bold text-foreground tabular-nums">
                            {result.fatLossMax}
                          </span>
                          <span className="text-sm text-muted-foreground ml-1">
                            大卡/天
                          </span>
                        </div>
                        <div className="mt-2 text-xs text-muted-foreground">
                          相当于 TDEE 的 80% ~ 90%
                        </div>
                      </div>

                      <div className="p-4 rounded-xl bg-card border border-border/60 space-y-2">
                        <div className="flex items-center gap-2 text-sm font-medium text-foreground">
                          <TrendingDown className="size-4 text-rose-500" />
                          每日热量缺口
                        </div>
                        <div className="flex items-baseline gap-1">
                          <span className="text-xl font-bold text-rose-500 tabular-nums">
                            {result.deficitMin}
                          </span>
                          <span className="text-muted-foreground">~</span>
                          <span className="text-xl font-bold text-rose-500 tabular-nums">
                            {result.deficitMax}
                          </span>
                          <span className="text-xs text-muted-foreground ml-1">
                            大卡
                          </span>
                        </div>
                        <p className="text-xs text-muted-foreground">
                          预计每周减重约 {result.weeklyLossMin} ~{' '}
                          {result.weeklyLossMax} 斤（每斤脂肪约 3850 大卡）
                        </p>
                      </div>
                    </motion.div>
                  ) : (
                    <motion.div
                      key="placeholder"
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      transition={{ duration: 0.4 }}
                      className="flex flex-col items-center justify-center h-full min-h-[280px] text-center space-y-3 bg-muted/30 rounded-xl border border-dashed border-border/60"
                    >
                      <Flame className="size-10 text-muted-foreground/50" />
                      <div>
                        <p className="text-sm font-medium text-muted-foreground">
                          填写完整信息
                        </p>
                        <p className="text-xs text-muted-foreground/70 mt-1">
                          自动计算你的每日热量需求
                        </p>
                      </div>
                    </motion.div>
                  )}
                </div>
              </div>
            </CardContent>
          </Card>
        </motion.div>
      </div>
    </section>
  );
}
