import { useState, useEffect } from 'react';
import { scopedStorage } from '@lark-apaas/client-toolkit-lite';
import Header from '@/components/Header';
import Footer from '@/components/Footer';
import HeroSection from './sections/HeroSection';
import BmiSection from './sections/BmiSection';
import TdeeSection from './sections/TdeeSection';
import WeightSection from './sections/WeightSection';
import FoodsSection from './sections/FoodsSection';
import ExerciseSection from './sections/ExerciseSection';

const PROFILE_KEY = 'fit_track_user_profile';

interface IUserProfile {
  height?: number;
  weight?: number;
  gender?: 'male' | 'female';
  age?: number;
  activityLevel?: number;
}

export default function HomePage() {
  const [profile, setProfile] = useState<IUserProfile>({
    height: '',
    weight: '',
    gender: 'male',
    age: '',
    activityLevel: 2,
  } as unknown as IUserProfile);
  const [loaded, setLoaded] = useState(false);

  // 初始加载 profile
  useEffect(() => {
    try {
      const raw = scopedStorage.getItem(PROFILE_KEY);
      if (raw) {
        const saved = JSON.parse(raw) as IUserProfile;
        setProfile((prev) => ({ ...prev, ...saved }));
      }
    } catch {
      /* ignore */
    }
    setLoaded(true);
  }, []);

  // 持久化
  useEffect(() => {
    if (!loaded) return;
    try {
      scopedStorage.setItem(PROFILE_KEY, JSON.stringify(profile));
    } catch {
      /* ignore */
    }
  }, [profile, loaded]);

  const updateProfile = (patch: Partial<IUserProfile>) => {
    setProfile((prev) => ({ ...prev, ...patch }));
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-background via-background to-primary/5">
      <Header />
      <main>
        <HeroSection />
        <BmiSection
          height={profile.height as number | ''}
          weight={profile.weight as number | ''}
          onHeightChange={(v) => updateProfile({ height: v as number })}
          onWeightChange={(v) => updateProfile({ weight: v as number })}
        />
        <TdeeSection
          gender={profile.gender as 'male' | 'female'}
          age={profile.age as number | ''}
          height={profile.height as number | ''}
          weight={profile.weight as number | ''}
          activityLevel={profile.activityLevel ?? 2}
          onGenderChange={(v) => updateProfile({ gender: v })}
          onAgeChange={(v) => updateProfile({ age: v as number })}
          onHeightChange={(v) => updateProfile({ height: v as number })}
          onWeightChange={(v) => updateProfile({ weight: v as number })}
          onActivityLevelChange={(v) => updateProfile({ activityLevel: v })}
        />
        <WeightSection />
        <FoodsSection />
        <ExerciseSection />
      </main>
      <Footer />
    </div>
  );
}
